import fs from "node:fs";
import assert from "node:assert/strict";
import {execFileSync,spawnSync} from "node:child_process";
import {createHash} from "node:crypto";
const r=JSON.parse(fs.readFileSync("docs/wi-execution-policy-c1-verification.json","utf8"));
const m=fs.readFileSync("docs/WI_EXECUTION_POLICY_C1_VERIFICATION.md","utf8").replace(/\s+/g," ");
const has=s=>assert(m.includes(s),"Markdown missing: "+s);
assert.deepEqual(r.matrix.map(x=>[x.id,x.status]),Array.from({length:18},(_,i)=>["C1-"+String(i).padStart(2,"0"),"PASS"]));
assert.equal(new Set(r.matrix.map(x=>x.id)).size,18);
for(const x of r.matrix) has("| "+x.id+" | PASS | "+x.assertion+" | "+x.evidence.join("; ")+" |");
assert.equal(r.evidence_catalog.length,14);
for(const x of r.evidence_catalog){has(x.assertion);for(const t of x.tests)has(t);}
assert.equal(r.retained_constraints.length,14);
for(const x of r.retained_constraints){has("| "+x.id+" |");has(x.setting);has(x.purpose_effect);}
assert.equal(r.test_migration.renamed_retained_coverage.length,6);
for(const x of r.test_migration.renamed_retained_coverage){has(x.path);has(x.old);has(x.new);}
for(const x of r.test_migration.deleted_or_replaced)has(x.old);
for(const x of r.questionable_retained_surface)for(const v of Object.values(x))has(v);
assert.equal(r.final_command_results.length,10);
for(const x of r.final_command_results){assert.equal(x.exit_code,0);assert.equal(x.status,"PASS");has(x.command);has(x.result);}
assert.deepEqual(r.test_counts.rust_executions,{baseline:244,final:260,delta:16});
assert.deepEqual(r.test_counts.verifier_rust_test_definition_inventory,{baseline:231,final:247,delta:16});
assert.equal(Object.values(r.final_command_results[2].targets).reduce((a,b)=>a+b,0),260);
has("244 -> 260 (+16)");has("231 -> 247 (+16)");
assert.equal(r.schema_version,1);assert.equal(r.implementation_changes.runtime_events.outer_schema,2);assert.equal(r.implementation_changes.runtime_events.provider_schema,1);
assert.equal(r.contract,"c1.1");assert.equal(r.implementation_commit,null);assert.equal(r.implementation_revision,"uncommitted_worktree");assert.equal(r.implementation_status,"complete_uncommitted");
for(const k of ["offline_gates","independent_review","offline_acceptance"])assert.equal(r[k],"PASS");assert.equal(r.accepted,true);assert.deepEqual(r.blockers,[]);has("Blockers: none.");
assert.deepEqual(r.ledger,{used:31,cap:50,remaining:19,changed:false,remaining_is_authorization:false});has("31/50 used, 19 remaining");
for(const k of ["real_auth","auth_profile_commands","live_provider_work"])assert.equal(r.live_status[k],"NOT RUN");
for(const k of ["real_credentials_read","authorized","live_started"])assert.equal(r.live_status[k],false);assert.equal(r.live_status.c1_live_provider_generations,0);has("C1 live provider generations: **0**");
for(const k of ["A","B","C"]){assert.equal(r.reviews.final_complete_diff[k],"COMPLETE-DIFF PASS");has("| Final independent complete-diff "+k+" | COMPLETE-DIFF PASS; no actionable findings |");}
assert.equal(r.reviews.increment_2_initial.severity,"medium");assert.equal(r.reviews.remediation.status,"PASS");has("clippy::await_holding_lock");
const git=(...args)=>execFileSync("git",args,{encoding:"utf8"});
assert.equal(git("rev-parse","HEAD").trim(),r.documentation_branch_head);assert.equal(r.documentation_branch_head,"870f3c4c4446d787114b7fd0c4e558d4838f851d");assert.equal(r.runtime_baseline_commit,"640b221b70dbb4d68704e6fa70d12f9533654cf5");has(r.documentation_branch_head);has(r.runtime_baseline_commit);
assert.equal(git("diff","--cached","--name-only"),"");
const c=r.changed_files;const expected=[...c.preexisting_modified_tracked.map(p=>" M "+p),...c.preexisting_untracked.map(p=>"?? "+p),...c.created_by_increment_4.map(p=>"?? "+p)].sort();
assert.deepEqual(git("status","--porcelain=v1").trimEnd().split("\n").sort(),expected);
for(const p of [...c.preexisting_modified_tracked,...c.preexisting_untracked,...c.created_by_increment_4,...c.unchanged_protected]){has(p);assert(fs.existsSync(p));}
assert.deepEqual(c.existing_files_modified_by_increment_4,[]);
const n=git("diff","--numstat").trimEnd().split("\n").map(s=>s.split("\t"));
assert.equal(n.length,17);assert.equal(n.reduce((s,x)=>s+Number(x[0]),0),1020);assert.equal(n.reduce((s,x)=>s+Number(x[1]),0),564);
assert.deepEqual(r.worktree_state.after_report_creation,{modified_tracked:17,untracked:3,staged_changes:0,implementation_commit:null});
const hash=b=>createHash("sha256").update(b).digest("hex");
const snapshot=r.worktree_state.preservation_snapshot;assert.equal(hash(execFileSync("git",["diff","--binary"])),snapshot.tracked_diff_sha256);assert.equal(hash(fs.readFileSync("tests/run_support/workloads.rs")),snapshot.workloads_sha256);has(snapshot.tracked_diff_sha256);has(snapshot.workloads_sha256);
assert.equal(r.report_checks.status,"PASS");has("Report-check status: **PASS**.");
for(const x of r.report_checks.command_results){assert.equal(x.status,"PASS");assert.equal(x.exit_code,["Q4","Q5","Q6"].includes(x.id)?1:0);}
for(const x of r.report_checks.command_results.slice(1)){
  const search=x.id==="Q2";
  const args=search?["-n","C1-[0-9]{2}|PENDING|NOT RUN|uncommitted|244|260|231|247|31/50|blockers|Blockers|schema_version","docs/WI_EXECUTION_POLICY_C1_VERIFICATION.md","docs/wi-execution-policy-c1-verification.json"]:x.command.split(" ").slice(1);
  const result=spawnSync(search?"rg":"git",args,{encoding:"utf8"});
  assert.equal(result.status,x.exit_code,x.id);assert.equal(result.stderr,"",x.id);
  if(search){assert(result.stdout.includes("C1-17"));assert(result.stdout.includes("NOT RUN"));}else assert.equal(result.stdout,"",x.id);
  console.log(x.id+" PASS: exit="+result.status+(search?"; consistency matches inspected":"; no whitespace diagnostics"));
}
console.log("PASS: strict JSON; 18 unique ordered PASS rows; 14 evidence records; 14 retained constraints; six migrations; ten parent command records; Markdown/JSON agreement; HEAD, staged state, paths and preservation hashes.");
